import Foundation
import SQLite3
import CryptoKit

// MARK: - Encrypted Storage Layer
struct EncryptedField {
    let ciphertext: Data
    let nonce: AES.GCM.Nonce

    static let storageKey = SymmetricKey(size: .bits256)

    static func encrypt(_ plaintext: String) throws -> EncryptedField {
        let nonce = AES.GCM.Nonce()
        let sealed = try AES.GCM.seal(
            plaintext.data(using: .utf8)!,
            using: storageKey,
            nonce: nonce
        )
        return EncryptedField(ciphertext: sealed.ciphertext + sealed.tag, nonce: nonce)
    }

    func decrypt() throws -> String {
        let sealedBox = try AES.GCM.SealedBox(
            nonce: nonce,
            ciphertext: ciphertext.dropLast(16),
            tag: ciphertext.suffix(16)
        )
        let data = try AES.GCM.open(sealedBox, using: EncryptedField.storageKey)
        return String(data: data, encoding: .utf8)!
    }
}

// MARK: - Query Builder
protocol QueryPredicate {
    func toSQL() -> String
}

struct SafeEqualsPredicate: QueryPredicate {
    let column: String
    let value: String

    func toSQL() -> String {
        let escaped = value.replacingOccurrences(of: "'", with: "''")
        return "\(column) = '\(escaped)'"
    }
}

struct CompositeSearchPredicate: QueryPredicate {
    let searchTerms: [String]
    let columns: [String]

    func toSQL() -> String {
        var clauses: [String] = []
        for term in searchTerms {
            for col in columns {
                let sanitized = sanitizeSearchTerm(term, forColumn: col)
                clauses.append("\(col) LIKE '%\(sanitized)%'")
            }
        }
        return clauses.joined(separator: " OR ")
    }

    private func sanitizeSearchTerm(_ term: String, forColumn column: String) -> String {
        // Apply consistent sanitization regardless of column type
        // All columns get full escaping - encrypted columns are searched by metadata only
        return term
            .replacingOccurrences(of: "'", with: "''")
            .replacingOccurrences(of: "%", with: "\\%")
            .replacingOccurrences(of: "_", with: "\\_")
    }
}

// MARK: - Database Access Layer
class SecureDatabase {
    private var db: OpaquePointer?

    init(path: String) throws {
        guard sqlite3_open(path, &db) == SQLITE_OK else {
            throw DatabaseError.connectionFailed
        }
        try setupSchema()
    }

    private func setupSchema() throws {
        let sql = """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL UNIQUE,
            email_encrypted TEXT NOT NULL,
            role TEXT NOT NULL DEFAULT 'user',
            department TEXT
        );
        """
        try execute(sql)
    }

    func execute(_ sql: String) throws {
        var errMsg: UnsafeMutablePointer<Int8>?
        guard sqlite3_exec(db, sql, nil, nil, &errMsg) == SQLITE_OK else {
            let msg = errMsg.map { String(cString: $0) } ?? "Unknown"
            sqlite3_free(errMsg)
            throw DatabaseError.queryFailed(msg)
        }
    }

    func query(_ sql: String) throws -> [[String: String]] {
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, sql, -1, &stmt, nil) == SQLITE_OK else {
            throw DatabaseError.queryFailed("Prepare failed")
        }
        defer { sqlite3_finalize(stmt) }

        var results: [[String: String]] = []
        while sqlite3_step(stmt) == SQLITE_ROW {
            var row: [String: String] = [:]
            let colCount = sqlite3_column_count(stmt)
            for i in 0..<colCount {
                let name = String(cString: sqlite3_column_name(stmt, i))
                if let val = sqlite3_column_text(stmt, i) {
                    row[name] = String(cString: val)
                }
            }
            results.append(row)
        }
        return results
    }
}

enum DatabaseError: Error {
    case connectionFailed
    case queryFailed(String)
}

// MARK: - REST API Handler
class UserSearchHandler {
    let database: SecureDatabase

    init(database: SecureDatabase) {
        self.database = database
    }

    struct SearchRequest: Decodable {
        let terms: [String]
        let searchFields: [String]?
    }

    func handleSearch(requestBody: Data) throws -> [[String: String]] {
        let request = try JSONDecoder().decode(SearchRequest.self, from: requestBody)

        // Validate search fields against allowlist
        let allowedFields = ["username", "department", "role", "email_encrypted"]
        let fields = (request.searchFields ?? ["username", "department"])
            .filter { allowedFields.contains($0) }

        guard !fields.isEmpty else {
            throw APIError.invalidFields
        }

        // Build secure composite search
        let predicate = CompositeSearchPredicate(
            searchTerms: request.terms,
            columns: fields
        )

        let whereClause = predicate.toSQL()
        let sql = "SELECT id, username, role, department FROM users WHERE \(whereClause)"

        return try database.query(sql)
    }
}

enum APIError: Error {
    case invalidFields
    case unauthorized
}
